47	func TestSaveReserveTimeoutPolicyValidation(t *testing.T) {
48		w, c := newTestWallet()
49		mustAccount(t, w, "payer", 100)
50		mustAccount(t, w, "u1", 0)
51		mustAccount(t, w, "u2", 0)
52	
53		// 正值：接受并可查询。
54		good := timeoutPolicy(c, 30*time.Second)
55		if err := w.SavePolicy(good); err != nil {
56			t.Fatal(err)
57		}
58		pv, err := w.Policy("p-timeout")
59		if err != nil {
60			t.Fatal(err)
61		}
62		if pv.MaxReserveDuration != 30*time.Second {
63			t.Fatalf("max reserve duration = %v, want 30s", pv.MaxReserveDuration)
64		}
65	
66		// 负值：策略无效且不创建策略。
67		neg := good
68		neg.ID = "p-neg"
69		neg.MaxReserveDuration = -time.Nanosecond
70		if err := w.SavePolicy(neg); !errors.Is(err, ErrPolicyInvalid) {
71			t.Fatalf("negative duration err = %v, want ErrPolicyInvalid", err)
72		}
73		if _, err := w.Policy("p-neg"); !errors.Is(err, ErrPolicyNotFound) {
74			t.Fatalf("negative-duration policy must not be created: %v", err)
75		}
76	
77		// 零：关闭超时，保持既有行为，允许保存并可查询为零。
78		off := timeoutPolicy(c, 0)
79		off.ID = "p-off"
80		if err := w.SavePolicy(off); err != nil {
81			t.Fatalf("zero duration should be accepted: %v", err)
82		}
83		offView, err := w.Policy("p-off")
84		if err != nil {
85			t.Fatal(err)
86		}
87		if offView.MaxReserveDuration != 0 {
88			t.Fatalf("disabled duration = %v, want 0", offView.MaxReserveDuration)
89		}
90	}
