92	func TestDirectApplyStartsTimerAtAcceptance(t *testing.T) {
93		w, c := setupTimeout(t, 30*time.Second)
94	
95		req, err := w.Apply(timeoutApply())
96		if err != nil {
97			t.Fatal(err)
98		}
99		if req.State != RequestReserved {
100			t.Fatalf("state = %v", req.State)
101		}
102		// 直接受理：实际预留时间为受理时刻，截止时间为受理时刻 + 最长预留时长。
103		if !req.ReservedAt.Equal(c.t) {
104			t.Fatalf("reservedAt = %v, want acceptance time %v", req.ReservedAt, c.t)
105		}
106		if req.ReserveDuration != 30*time.Second {
107			t.Fatalf("reserve duration = %v", req.ReserveDuration)
108		}
109		if !req.ReserveDeadline.Equal(c.t.Add(30 * time.Second)) {
110			t.Fatalf("deadline = %v, want %v", req.ReserveDeadline, c.t.Add(30*time.Second))
111		}
112		if !req.ReserveExpiredAt.IsZero() {
113			t.Fatalf("release time before timeout = %v, want zero", req.ReserveExpiredAt)
114		}
115	}
