311	func TestReservationTimeoutLedgerEntries(t *testing.T) {
312		w, c := setupTimeout(t, 30*time.Second)
313		if _, err := w.Apply(timeoutApply()); err != nil {
314			t.Fatal(err)
315		}
316		c.t = c.t.Add(time.Minute)
317		if _, err := w.Request("u1", "r1"); err != nil {
318			t.Fatal(err)
319		}
320	
321		// 出资账户：原预留保留，新增一条全额退款（金额 20，关联请求）。
322		payerLedger := w.AccountLedger("payer")
323		if len(payerLedger) != 2 ||
324			payerLedger[0].Kind != LedgerReserve || payerLedger[0].Amount != 20 ||
325			payerLedger[1].Kind != LedgerRefund || payerLedger[1].Amount != 20 {
326			t.Fatalf("payer ledger = %+v", payerLedger)
327		}
328		for _, e := range payerLedger {
329			if e.RequestID != "r1" {
330				t.Fatalf("entry missing request link: %+v", e)
331			}
332		}
333		if payerLedger[1].Reason == "" {
334			t.Fatal("refund reason must explain the timeout")
335		}
336		if payerLedger[1].At != c.t.Add(-30*time.Second) {
337			t.Fatalf("refund recorded at %v, want deadline %v", payerLedger[1].At, c.t.Add(-30*time.Second))
338		}
339	
340		// 使用账户：一条零金额超时记录，关联请求并说明原因。
341		usageLedger := w.AccountLedger("u1")
342		if len(usageLedger) != 1 ||
343			usageLedger[0].Kind != LedgerReservationExpiration ||
344			usageLedger[0].Amount != 0 || usageLedger[0].RequestID != "r1" ||
345			usageLedger[0].Reason == "" {
346			t.Fatalf("usage ledger = %+v", usageLedger)
347		}
348		// 状态记录不得混入出资账户账本，资金记录不得混入使用账户账本。
349		if countKind(w.AccountLedger("payer"), LedgerReservationExpiration) != 0 {
350			t.Fatal("payer ledger must not carry timeout status entry")
351		}
352		for _, e := range w.AccountLedger("u1") {
353			if e.Kind == LedgerReserve || e.Kind == LedgerRefund {
354				t.Fatalf("usage ledger must not carry money movement: %+v", e)
355			}
356		}
357	}
