359	func TestSettleAfterReservationTimeout(t *testing.T) {
360		w, c := setupTimeout(t, 30*time.Second)
361		if _, err := w.Apply(timeoutApply()); err != nil {
362			t.Fatal(err)
363		}
364		c.t = c.t.Add(30 * time.Second) // 恰为截止时刻
365	
366		// 非负实际费用的结算返回明确的预留已超时错误，不能扣款。
367		if _, err := w.Settle("u1", "r1", 20); !errors.Is(err, ErrReservationExpired) {
368			t.Fatalf("settle at deadline err = %v, want ErrReservationExpired", err)
369		}
370		if _, err := w.Settle("u1", "r1", 0); !errors.Is(err, ErrReservationExpired) {
371			t.Fatalf("zero-fee settle err = %v, want ErrReservationExpired", err)
372		}
373		// 重复迟到结算仍然失败，绝不补扣。
374		if _, err := w.Settle("u1", "r1", 5); !errors.Is(err, ErrReservationExpired) {
375			t.Fatalf("late settle err = %v, want ErrReservationExpired", err)
376		}
377		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 100, Reserved: 0}) {
378			t.Fatalf("balance = %+v, want fully refunded {100 0}", bal)
379		}
380		pv, _ := w.Policy("p-timeout")
381		if pv.SpentTotal != 0 {
382			t.Fatalf("spent total = %d, want 0", pv.SpentTotal)
383		}
384		req, _ := w.Request("u1", "r1")
385		if req.State != RequestReservationExpired || req.ActualFee != 0 {
386			t.Fatalf("request = %+v", req)
387		}
388	}
