390	func TestCancelAfterReservationTimeoutIsIdempotent(t *testing.T) {
391		w, c := setupTimeout(t, 30*time.Second)
392		if _, err := w.Apply(timeoutApply()); err != nil {
393			t.Fatal(err)
394		}
395		c.t = c.t.Add(time.Minute)
396	
397		// 取消返回已有的超时结果，不重复退回。
398		view, err := w.Cancel("u1", "r1")
399		if err != nil {
400			t.Fatalf("cancel after timeout: %v", err)
401		}
402		if view.State != RequestReservationExpired {
403			t.Fatalf("cancel view state = %v, want reservation expired", view.State)
404		}
405		if again, err := w.Cancel("u1", "r1"); err != nil || again.State != RequestReservationExpired {
406			t.Fatalf("repeat cancel: %+v %v", again, err)
407		}
408		// 退款只发生一次。
409		if n := countKind(w.Ledger(), LedgerRefund); n != 1 {
410			t.Fatalf("refund entries = %d, want exactly 1", n)
411		}
412		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 100, Reserved: 0}) {
413			t.Fatalf("balance = %+v", bal)
414		}
415	}
