417	func TestReapplyAfterReservationTimeout(t *testing.T) {
418		w, c := setupTimeout(t, 30*time.Second)
419		if _, err := w.Apply(timeoutApply()); err != nil {
420			t.Fatal(err)
421		}
422		c.t = c.t.Add(time.Minute)
423		before := len(w.Ledger())
424	
425		// 通过既有会话校验的同号同内容申请：返回超时结果，不重复预留、不留痕。
426		view, err := w.Apply(timeoutApply())
427		if err != nil {
428			t.Fatalf("idempotent re-apply: %v", err)
429		}
430		if view.State != RequestReservationExpired {
431			t.Fatalf("re-apply state = %v, want reservation expired", view.State)
432		}
433		if len(w.Ledger()) != before {
434			t.Fatal("re-apply produced ledger entries")
435		}
436		// 同号不同内容仍返回冲突。
437		conflict := timeoutApply()
438		conflict.EstimatedFee = 19
439		if _, err := w.Apply(conflict); !errors.Is(err, ErrConflict) {
440			t.Fatalf("conflict err = %v, want ErrConflict", err)
441		}
442		// 重新发起必须换请求编号：新编号可正常受理并复用已退回的费用。
443		retry := timeoutApply()
444		retry.RequestID = "r2"
445		if r2, err := w.Apply(retry); err != nil || r2.State != RequestReserved {
446			t.Fatalf("fresh request after timeout: %+v %v", r2, err)
447		}
448		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 80, Reserved: 20}) {
449			t.Fatalf("balance = %+v, want {80 20}", bal)
450		}
451	}
