479		if _, err := w.Approve("u1", "r1", "sa", "dev-approve"); !errors.Is(err, ErrRequestNotPending) {
480			t.Fatalf("re-approve after timeout err = %v, want ErrRequestNotPending", err)
481		}
482		// 审批身份校验仍按现有规则：无效会话先返回无权审批。
483		if _, err := w.Approve("u1", "r1", "nope", "dev-approve"); !errors.Is(err, ErrNotApprover) {
484			t.Fatalf("bad approver session err = %v, want ErrNotApprover", err)
485		}
486		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 100, Reserved: 0}) {
487			t.Fatalf("balance = %+v", bal)
488		}
489	}
